/// lightbox: Gallery of three images
private struct LightboxExample0: View {
    @State private var isShown = PreviewMode.presented ? true : false
    @State private var index = 0
    private let buttonLabel = "View image"

    private static let picture: Image = {
        let width = 1200, height = 800
        guard let context = CGContext(
            data: nil, width: width, height: height, bitsPerComponent: 8, bytesPerRow: 0,
            space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else { return Image(systemName: "photo") }
        context.setFillColor(red: 0.58, green: 0.64, blue: 0.74, alpha: 1)
        context.fill(CGRect(x: 0, y: 0, width: width, height: height))
        guard let picture = context.makeImage() else { return Image(systemName: "photo") }
        return Image(decorative: picture, scale: 1)
    }()

    private let photos = [
        MonarchLightboxItem(image: Self.picture, alt: "Planning board with three columns of notes", caption: "Sprint planning board"),
        MonarchLightboxItem(image: Self.picture, alt: "Pencil sketch of a settings screen", caption: "Settings sketch"),
        MonarchLightboxItem(image: Self.picture, alt: "Plain sample image in a warm grey"),
    ]

    var body: some View {
        HStack {
            ForEach(photos.indices, id: \.self) { i in
                MonarchButton("\(buttonLabel) \(i + 1)") {
                    index = i
                    isShown = true
                }
            }
        }
        .monarchLightbox(isPresented: $isShown, items: photos, selection: $index)
    }
}

