/// peek-panel: Preview orders from a list
private struct PeekPanelExample0: View {
    @Environment(\.monarchTheme) private var theme
    struct Order {
        let id: String
        let status: String
        let total: String
    }

    @State private var selected: Int? = 1

    private let orders = [
        Order(id: "Order 1001", status: "Paid", total: "€120.00"),
        Order(id: "Order 1002", status: "Awaiting payment", total: "€48.50"),
        Order(id: "Order 1003", status: "Refunded", total: "€15.00"),
    ]

    private var isShown: Binding<Bool> {
        Binding(get: { selected != nil }, set: { if !$0 { selected = nil } })
    }

    var body: some View {
        List(orders.indices, id: \.self) { index in
            Button(orders[index].id) { selected = index }
                .listRowBackground(Color.clear)
        }
        .inspector(isPresented: isShown) {
            if let index = selected {
                VStack(alignment: .leading, spacing: 0) {
                    HStack(spacing: MonarchTokens.Space.space2) {
                        MonarchButton("Previous", systemImage: "chevron.up", variant: .ghost, size: .sm, isIconOnly: true) { selected = index - 1 }
                            .disabled(index == 0)
                        MonarchButton("Next", systemImage: "chevron.down", variant: .ghost, size: .sm, isIconOnly: true) { selected = index + 1 }
                            .disabled(index == orders.count - 1)
                        Text("\(index + 1) of \(orders.count)")
                            .monarchTextStyle(.caption)
                            .foregroundStyle(theme.colors.textMuted)
                        Spacer(minLength: 0)
                        Button("Open full record") {}
                            .buttonStyle(.monarchLink(.inline))
                            .monarchTextStyle(.bodySmall)
                        MonarchButton("Close", systemImage: "xmark", variant: .ghost, size: .sm, isIconOnly: true) { selected = nil }
                    }
                    .padding(MonarchTokens.Space.space3)
                    MonarchDivider()
                    VStack(alignment: .leading, spacing: MonarchTokens.Space.space1) {
                        Text(orders[index].id).monarchTextStyle(.heading).foregroundStyle(theme.colors.textDefault)
                        Text(orders[index].status).monarchTextStyle(.body).foregroundStyle(theme.colors.textMuted)
                        Text("Total " + orders[index].total)
                            .monarchTextStyle(.body)
                            .foregroundStyle(theme.colors.textDefault)
                            .padding(.top, MonarchTokens.Space.space4)
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .padding(MonarchTokens.Space.space4)
                    Spacer(minLength: 0)
                    MonarchDivider()
                    HStack {
                        Spacer(minLength: 0)
                        MonarchButton("Send receipt", variant: .primary) {}
                    }
                    .padding(MonarchTokens.Space.space3)
                    .background(theme.colors.bgSubtle)
                }
                .presentationDetents([.medium, .large])
                .inspectorColumnWidth(min: 280, ideal: 360, max: 480)
            }
        }
        .listStyle(.plain)
        .scrollContentBackground(.hidden)
        .monarchCanvas()
    }
}

/// popconfirm: Remove a filter
private struct PopconfirmExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var filters = ["Status: Open", "Owner: Me"]
    @State private var pending = "Status: Open"
    @State private var isConfirming = PreviewMode.presented ? true : false

    var body: some View {
        HStack {
            ForEach(filters, id: \.self) { filter in
                MonarchButton(filter, variant: .secondary, size: .sm) {
                    pending = filter
                    isConfirming = true
                }
                .popover(
                    isPresented: Binding(
                        get: { isConfirming && pending == filter },
                        set: { if !$0 { isConfirming = false } }
                    ),
                    arrowEdge: .top
                ) {
                    VStack(alignment: .leading, spacing: theme.spacing.space3) {
                        Text("Remove this filter?")
                            .monarchTextStyle(.bodyStrong)
                            .accessibilityAddTraits(.isHeader)
                        Text("The list shows matching items again.").monarchTextStyle(.body)
                        HStack(spacing: theme.spacing.space2) {
                            Spacer(minLength: 0)
                            MonarchButton("Cancel", variant: .secondary, size: .sm) { isConfirming = false }
                            MonarchButton("Remove", variant: .danger, size: .sm) {
                                filters.removeAll { $0 == pending }
                                isConfirming = false
                            }
                        }
                    }
                    .foregroundStyle(theme.colors.textDefault)
                    .padding(theme.spacing.space4)
                    .presentationCompactAdaptation(.popover)
                    .presentationBackground(theme.colors.bgRaised)
                }
            }
        }
    }
}

