/// responsive-dialog: Invite form
private struct ResponsiveDialogExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var isOpen = PreviewMode.presented ? true : true
    @State private var email = ""

    var body: some View {
        MonarchButton("Invite people") { isOpen = true }
            .sheet(isPresented: $isOpen) {
                NavigationStack {
                    VStack(alignment: .leading, spacing: theme.spacing.space4) {
                        Text("They get an email with a link to join.")
                            .monarchTextStyle(.body)
                            .foregroundStyle(theme.colors.textMuted)
                        MonarchTextField("Email address", text: $email, prompt: "name@example.com")
                    }
                    .padding(theme.spacing.space4)
                    .frame(maxHeight: .infinity, alignment: .top)
                    .navigationTitle("Invite people")
                    #if os(iOS)
                    .navigationBarTitleDisplayMode(.inline)
                    #endif
                    .toolbar {
                        ToolbarItem(placement: .cancellationAction) {
                            Button("Cancel") { isOpen = false }
                        }
                        ToolbarItem(placement: .confirmationAction) {
                            Button("Send invite") { isOpen = false }
                        }
                    }
                }
                .presentationDetents([.medium, .large])
                .presentationDragIndicator(.visible)
                .presentationBackground(theme.colors.bgSurface)
            }
    }
}

/// sheet: Record details
private struct SheetExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var isOpen = true

    var body: some View {
        MonarchButton("Open details") { isOpen = true }
            .sheet(isPresented: $isOpen) {
                VStack(alignment: .leading, spacing: 0) {
                VStack(alignment: .leading, spacing: theme.spacing.space4) {
                    HStack(alignment: .top) {
                        Text("Invoice INV-1042")
                            .monarchTextStyle(.heading)
                            .accessibilityAddTraits(.isHeader)
                        Spacer(minLength: 0)
                        Button { isOpen = false } label: {
                            MonarchIcon(systemName: "xmark", size: .sm).monarchMinimumHitTarget()
                        }
                        .buttonStyle(.plain)
                        .accessibilityLabel("Close")
                    }
                    Text("Sent on 12 March to the billing contact.")
                        .monarchTextStyle(.caption)
                        .foregroundStyle(theme.colors.textMuted)
                    LazyVGrid(columns: [GridItem(.flexible(), alignment: .topLeading), GridItem(.flexible(), alignment: .topLeading)], alignment: .leading, spacing: theme.spacing.space3) {
                        LabeledContent("Status", value: "Awaiting payment")
                            .labeledContentStyle(.monarch)
                        LabeledContent("Due", value: "26 March")
                            .labeledContentStyle(.monarch)
                        LabeledContent("Owner", value: "Priya Raman")
                            .labeledContentStyle(.monarch)
                    }
                }
                .padding(theme.spacing.space4)
                    // The footer is a bar of its own, with the actions at the end, as on the web.
                    HStack(spacing: theme.spacing.space2) {
                        Spacer(minLength: 0)
                        MonarchButton("Close") { isOpen = false }
                        MonarchButton("Send reminder", variant: .primary) { isOpen = false }
                    }
                    .padding(theme.spacing.space3)
                    .background(theme.colors.bgSubtle)
                }
                .foregroundStyle(theme.colors.textDefault)
                .frame(maxHeight: .infinity, alignment: .top)
                .presentationDetents([.medium, .large])
                .presentationDragIndicator(.visible)
                .presentationBackground(theme.colors.bgSurface)
            }
    }
}

/// sheet: A sheet that cannot be swiped away while saving
private struct SheetExample1: View {
    @State private var isShown = false
    @State private var isSaving = false

    var body: some View {
        MonarchButton("Import contacts") { isShown = true }
            .sheet(isPresented: $isShown) {
                VStack {
                    MonarchButton("Import", variant: .primary, isLoading: isSaving) { isSaving = true }
                    MonarchButton("Cancel", variant: .ghost) { isShown = false }
                        .disabled(isSaving)
                }
                .padding()
                .interactiveDismissDisabled(isSaving)
            }
    }
}

/// terms-update-dialog: Blocking, with sign out
private struct TermsUpdateDialogExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var isShown = PreviewMode.presented ? true : false
    @State private var isAccepting = false
    private let effective = Date(timeIntervalSince1970: 1_796_083_200)
    private let locale = Locale(identifier: "en-GB")
    private let termsURL = URL(string: "https://example.com/terms")
    private let privacyURL = URL(string: "https://example.com/privacy")

    var body: some View {
        MonarchButton("Show blocking update") { isShown = true }
            .sheet(isPresented: $isShown) {
                VStack(alignment: .leading, spacing: theme.spacing.space4) {
                    ScrollView {
                        VStack(alignment: .leading, spacing: theme.spacing.space3) {
                            Text("We’ve updated our terms")
                                .monarchTextStyle(.heading)
                                .accessibilityAddTraits(.isHeader)
                            Text("Effective from \(effective.formatted(Date.FormatStyle(date: .long, time: .omitted).locale(locale)))")
                                .monarchTextStyle(.bodySmall)
                                .foregroundStyle(theme.colors.textMuted)
                            Text("Here is what changed:")
                                .monarchTextStyle(.bodySmall)
                                .foregroundStyle(theme.colors.textMuted)
                            VStack(alignment: .leading, spacing: theme.spacing.space1) {
                                Text("• " + "We explain how long we keep support messages.")
                                Text("• " + "We list the providers that host your data.")
                            }
                            .monarchTextStyle(.bodySmall)
                            .foregroundStyle(theme.colors.textMuted)
                            VStack(alignment: .leading, spacing: theme.spacing.space1) {
                                Text("Read the full documents")
                                    .monarchTextStyle(.label)
                                if let termsURL {
                                HStack(alignment: .firstTextBaseline, spacing: 0) {
                                    Link("Terms of Service", destination: termsURL)
                                        .buttonStyle(.monarchLink(.inline))
                                    Text(" (version " + "2026-12-01" + ")")
                                        .foregroundStyle(theme.colors.textMuted)
                                }
                                .monarchTextStyle(.bodySmall)
                                }
                                if let privacyURL {
                                HStack(alignment: .firstTextBaseline, spacing: 0) {
                                    Link("Privacy Policy", destination: privacyURL)
                                        .buttonStyle(.monarchLink(.inline))
                                    Text(" (version " + "2026-12-01" + ")")
                                        .foregroundStyle(theme.colors.textMuted)
                                }
                                .monarchTextStyle(.bodySmall)
                                }
                            }
                        }
                        .frame(maxWidth: .infinity, alignment: .leading)
                    }
                    HStack(spacing: theme.spacing.space2) {
                        Spacer(minLength: 0)
                        MonarchButton("Sign out", variant: .secondary) { isShown = false }
                        MonarchButton("Accept and continue", variant: .primary, isLoading: isAccepting) {
                            isAccepting = true
                            isShown = false
                        }
                    }
                }
                .foregroundStyle(theme.colors.textDefault)
                .padding(theme.spacing.space4)
                .interactiveDismissDisabled()
                .presentationDetents([.height(460)])
                .presentationBackground(theme.colors.bgSurface)
            }
    }
}

/// tooltip: On an icon button
private struct TooltipExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var showsTip = PreviewMode.presented ? true : false

    var body: some View {
        VStack(spacing: theme.spacing.space2) {
            if showsTip {
                Text("Copy link")
                    .monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.textInverse)
                    .fixedSize()
                    .padding(.horizontal, theme.spacing.space2)
                    .padding(.vertical, theme.spacing.space1)
                    .background(theme.colors.bgInverse, in: RoundedRectangle(cornerRadius: 6, style: .continuous))
                    .allowsHitTesting(false)
                    .transition(.opacity)
            }
            Button {
            } label: {
                MonarchIcon(systemName: "link")
            }
            .buttonStyle(.monarch(.ghost))
            .accessibilityLabel("Copy link")
            .help("Copy link")
            .onLongPressGesture { showsTip = true }
        }
    }
}

/// unsaved-changes-guard: Leaving with unsaved changes
private struct UnsavedChangesGuardExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var name = "Weekly planning v2"
    @State private var page = "Editor"
    @State private var isAsking = PreviewMode.presented ? true : false

    var body: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space3) {
            MonarchTextField("Board name", text: $name)
            HStack(spacing: theme.spacing.space2) {
                MonarchButton("Save", variant: .primary) {}
                MonarchButton("Go to overview") { isAsking = true }
            }
            Text("Current page: " + page)
        }
        .padding()
        .monarchUnsavedChangesGuard(
            isPresented: $isAsking,
            hasChanges: true,
            labels: MonarchUnsavedChangesGuardLabels(
                title: "Discard unsaved changes?",
                message: "Your changes have not been saved. If you leave now, they will be lost.",
                keepEditing: "Keep editing",
                discard: "Discard changes",
                save: "Save and leave"
            ),
            onSave: { try await Task.sleep(for: .milliseconds(600)) },
            onLeave: { _ in page = "Overview" }
        )
    }
}

/// unsaved-changes-guard: A pushed screen whose back button asks first
private struct UnsavedChangesGuardExample1: View {
    @State private var notes = ""
    @State private var isAsking = false
    @Environment(\.dismiss) private var dismiss

    var body: some View {
        TextField("Notes", text: $notes, axis: .vertical)
            .monarchTextStyle(.body)
            .navigationTitle("Notes")
            .monarchUnsavedChangesGuard(
                isPresented: $isAsking,
                hasChanges: !notes.isEmpty,
                onLeave: { _ in dismiss() }
            )
    }
}

/// wizard-dialog: Review, export, confirm, done
private struct WizardDialogExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var isOpen = PreviewMode.presented ? true : true
    @State private var step = 0
    @State private var exported = false
    private let steps = [
        MonarchStepperStep(id: "review", label: "What happens"),
        MonarchStepperStep(id: "export", label: "Keep a copy"),
        MonarchStepperStep(id: "confirm", label: "Close the project"),
    ]

    var body: some View {
        MonarchButton("Close project", variant: .danger) {
            step = 0
            isOpen = true
        }
        .sheet(isPresented: $isOpen) {
            NavigationStack {
                VStack(alignment: .leading, spacing: theme.spacing.space4) {
                    Text("Closing removes the project for everyone.")
                        .monarchTextStyle(.body)
                    if step < steps.count {
                        MonarchStepper(steps, current: step, compact: .always)
                    }
                    Text(step < steps.count ? steps[step].label : "Project closed")
                        .monarchTextStyle(.subheading)
                        .accessibilityAddTraits(.isHeader)
                    switch step {
                    case 0:
                        HStack(alignment: .firstTextBaseline, spacing: theme.spacing.space2) {
                            Text("•")
                            Text("48 tasks are archived")
                        }
                        .monarchTextStyle(.body)
                        HStack(alignment: .firstTextBaseline, spacing: theme.spacing.space2) {
                            Text("•")
                            Text("6 people lose access")
                        }
                        .monarchTextStyle(.body)
                    case 1:
                        Text("Download the tasks and comments before you continue.").monarchTextStyle(.body)
                        Toggle("I have downloaded a copy, or I do not need one", isOn: $exported)
                            .toggleStyle(.monarchCheckbox)
                        if !exported {
                            Text("Tick the box to continue.").monarchTextStyle(.caption)
                        }
                    case 2:
                        Text("You can reopen it from Archive for 30 days.").monarchTextStyle(.body)
                    default:
                        Text("It is in Archive.").monarchTextStyle(.body)
                    }
                    Spacer(minLength: 0)
                    HStack {
                        if step > 0 && step < steps.count {
                            MonarchButton("Back") { step -= 1 }
                        }
                        Spacer(minLength: 0)
                        if step < steps.count {
                            MonarchButton(
                                step == steps.count - 1 ? "Close project" : "Continue",
                                variant: step == steps.count - 1 ? .danger : .primary
                            ) {
                                step += 1
                            }
                            .disabled(step == 1 && !exported)
                        } else {
                            MonarchButton("Close") { isOpen = false }
                        }
                    }
                }
                .padding(theme.spacing.space4)
                .navigationTitle("Close project")
                #if os(iOS)
                .navigationBarTitleDisplayMode(.inline)
                #endif
                .toolbar {
                    ToolbarItem(placement: .cancellationAction) {
                        Button("Cancel") { isOpen = false }
                    }
                }
            }
            .interactiveDismissDisabled(step > 0 && step < steps.count)
            .presentationBackground(theme.colors.bgSurface)
        }
    }
}
